import {pricePages} from './slope-equation-content.mjs';
import {priceView,priceTotal,priceInteger,startPrice,setPricePage,setPriceX,setPriceField,showPriceHelp,checkPrice,keepPrice} from './slope-equation-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(a,t,p=false)=>`<button type="button" class="${p?'primary':'secondary'}" ${a}>${esc(t)}</button>`;
export const priceEntry=()=>`<aside class="price-entry"><a href="#desk/linear">The Courier’s Price</a><p>Turn a steady rate into an equation. Try a delivery card, change the distance and find a missing input.</p></aside>`;
function table(s,x,partner=false){return `<div class="price-table"><table><caption>${partner?'Two cards at the same distances':'Distance and total · invented price model'}</caption><thead><tr><th scope="col">x · km</th><th scope="col">${partner?esc(s.title):'y · coins'}</th>${partner?`<th scope="col">${esc(s.comparison.title)}</th>`:''}</tr></thead><tbody>${Array.from({length:7},(_,n)=>`<tr${n===x?' class="price-current"':''}><th scope="row">${n}</th><td>${priceTotal(s,n)}</td>${partner?`<td>${priceTotal(s.comparison,n)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function graph(s,x,comparison=false){const X=n=>45+45*n,Y=n=>215-9*n;return `<figure class="price-graph"><svg viewBox="0 0 360 265" role="img" aria-label="${esc(comparison?`${s.title} and ${s.comparison.title}, total price against distance on the same axes. See the table for every point.`:`${s.title}: from zero to six kilometers, the line starts at ${s.b} coins and rises ${s.m} coins for each kilometer. Current point: ${x} kilometers, ${priceTotal(s,x)} coins.`)}"><title>Total price against distance</title><desc>Horizontal axis: kilometers from 0 to 6. Vertical axis: coins from 0 to 20. The two axes use different units and scales; compare numerical changes, not a visual angle.</desc>${[0,5,10,15,20].map(n=>`<path d="M45 ${Y(n)}H315" stroke="#c4d3ce"/><text x="35" y="${Y(n)+5}" text-anchor="end">${n}</text>`).join('')}<path d="M45 25V215H325" stroke="#263e42" fill="none" stroke-width="2"/>${Array.from({length:7},(_,n)=>`<text x="${X(n)}" y="239" text-anchor="middle">${n}</text>`).join('')}<text x="12" y="18">coins</text><text x="281" y="260">km</text><path d="M45 ${Y(s.b)}L315 ${Y(priceTotal(s,6))}" stroke="#234f60" stroke-width="3" fill="none"/>${!comparison?`<g class="price-rise-run"><path d="M${X(4)} ${Y(priceTotal(s,4))}H${X(5)}V${Y(priceTotal(s,5))}" fill="none" stroke="#815236" stroke-width="2" stroke-dasharray="4 3"/><text x="${X(4)-24}" y="${Y(priceTotal(s,4))-15}">(4, ${priceTotal(s,4)})</text><text x="${X(5)+5}" y="${Y(priceTotal(s,5))-14}">(5, ${priceTotal(s,5)})</text><text x="${X(4)-3}" y="${Y(priceTotal(s,4))+21}">+1 km</text><text x="${X(5)+5}" y="${Y(priceTotal(s,4))-4}">+${s.m} coins</text></g>`:''}${comparison?`<path d="M45 ${Y(s.comparison.b)}L315 ${Y(priceTotal(s.comparison,6))}" stroke="#9b4f33" stroke-width="3" stroke-dasharray="8 5"/>`:''}${Array.from({length:7},(_,n)=>`<circle cx="${X(n)}" cy="${Y(priceTotal(s,n))}" r="3.5" fill="#234f60"/>`).join('')}<circle cx="${X(x)}" cy="${Y(priceTotal(s,x))}" r="7" fill="#f3cd79" stroke="#263e42" stroke-width="2"/></svg><figcaption>${comparison?`Solid: ${esc(s.title)}. Dashed: ${esc(s.comparison.title)}.`:'The line models prices between the pictured whole-kilometer points.'} The table gives exact values. ${comparison?'':`The marked step from 4 to 5 km has a run of 1 km and a rise of ${s.m} coins.`}</figcaption></figure>`;}
function source(s){return `<aside class="price-source"><strong>${esc(s.title)}</strong><p><span class="price-fixed">Bag charge once: ${s.b} coins</span><br>Each kilometer: ${s.m} coins</p><p>x = distance in kilometers · y = total in coins.<br>This invented card covers 0–6 km.</p></aside>`;}
function equation(s,x){return `${s.b} coins + ${x} km × ${s.m} coins/km = ${priceTotal(s,x)} coins`;}
function helpText(w){const s=w.source,n=(s.target-s.b)/s.m;return w.page===3?s.comparison.explanation:w.page===2?`Start with ${s.target} coins. Remove the ${s.b}-coin bag charge once: ${s.target} − ${s.b} = ${s.target-s.b}. Each kilometer uses ${s.m} coins, so ${s.target-s.b} ÷ ${s.m} = ${n} kilometers. Check: ${s.m} × ${n} + ${s.b} = ${s.target}.`:`At zero kilometers, y is ${s.b}. One more kilometer adds ${s.m} coins. So m = ${s.m} and b = ${s.b}. At ${w.x} kilometers, ${equation(s,w.x)}. The bag charge is not repeated.`;}
const field=(w,k,label)=>`<label>${esc(label)}<input type="text" inputmode="numeric" autocomplete="off" spellcheck="false" maxlength="40" data-price-field="${k}" value="${esc(w.drafts[k])}"></label>`;
function turn(w){const s=w.source;let t;
 if(w.page===0)t=`<p class="price-kicker">Start with one extra kilometer</p><h2 id="price-turn" tabindex="-1">What changes when the journey grows?</h2><p>The bag charge stays fixed. Every extra kilometer adds ${s.m} coins: one more group of ${s.m}.</p><div class="price-stepper">${btn(`data-price-delta="-1" aria-label="One kilometer less" aria-disabled="${w.x===0}"`,'−')}<label>Distance in kilometers<input type="text" inputmode="numeric" data-price-x maxlength="1" value="${w.x}" aria-describedby="price-x-state"></label>${btn(`data-price-delta="1" aria-label="One kilometer more" aria-disabled="${w.x===6}"`,'+')}</div><p class="price-equation" id="price-x-state">${equation(s,w.x)}</p><div class="price-batches" role="img" aria-label="${w.x} groups of ${s.m} route coins, plus ${s.b} starting coins"><span class="price-bag" aria-hidden="true">Bag<br><strong>${s.b}</strong></span>${Array.from({length:w.x},(_,n)=>`<span class="price-batch" aria-hidden="true">km ${n+1}<br>${'●'.repeat(s.m)}</span>`).join('')}</div><p>From 0 km to 1 km: ${s.b} → ${s.b+s.m} coins. Rise: ${s.m} coins for a run of 1 km. That rate is the <strong>slope</strong>.</p><p>A point (x, y) names distance first, then price. At (0, ${s.b}), distance is zero and the price is ${s.b} coins. A starting charge at zero is part of this pretend price rule.</p>`;
 else if(w.page===1)t=`<p class="price-kicker">The same relationship, written with letters</p><h2 id="price-turn" tabindex="-1">Which numbers belong in the rule?</h2><p class="price-equation">y = m × x + b</p><dl class="price-key"><dt>x</dt><dd>distance in kilometers</dd><dt>y</dt><dd>total price in coins</dd><dt>m</dt><dd>rate: coins for each kilometer (slope)</dd><dt>b</dt><dd>starting charge in coins (intercept: where the line meets the coins axis at x = 0)</dd></dl><p>Bag charge + distance × rate becomes b + x × m. Swap the two parts being added, and write x × m as m × x: b + x × m = m × x + b. Multiply first, then add the starting charge.</p>${field(w,'m','m · coins per kilometer')}${field(w,'b','b · starting coins')}${btn('data-price-check="rule"','Check my rule',true)}`;
 else if(w.page===2)t=`<p class="price-kicker">One total, a missing input</p><h2 id="price-turn" tabindex="-1">How far does ${s.target} coins take this delivery?</h2><p class="price-equation">${s.target} = ${s.m} × x + ${s.b}</p><p>The rule works for every distance in this model. Here, find the <em>one</em> whole-number distance that makes this total.</p>${field(w,'distance','Distance x · kilometers')}${btn('data-price-check="distance"','Check this distance',true)}<p>One way back: remove the starting charge once, then divide the remaining coins by the price for each kilometer. Substitute the distance to check it.</p>`;
 else t=`<p class="price-kicker">Compare two rules on the same axes</p><h2 id="price-turn" tabindex="-1">${s.m===s.comparison.m?'Same rate, different start: what changes?':'Does a steeper line always mean a higher total?'}</h2><p>Read and compare this worked example. Nothing on this page is checked.</p><p>${esc(s.comparison.explanation)}</p><div class="price-comparison">${graph(s,w.x,true)}${table(s,w.x,true)}</div><p>${esc(s.title)}: y = ${s.m} × x + ${s.b}.<br>${esc(s.comparison.title)}: y = ${s.comparison.m} × x + ${s.comparison.b}.</p><label>Your explanation or a question to follow (optional)<textarea data-price-field="note" rows="3" maxlength="800" placeholder="What stayed the same? What changed?">${esc(w.drafts.note)}</textarea></label>${btn('data-price-keep','Keep this page',true)}${w.kept?'<p class="price-kept">Page kept. You can revise it, try another card, or bring the idea to a crossing plan.</p>':''}<a class="secondary" href="#desk">Try the crossing case</a>`;
 const last=w.checks.filter(c=>c.kind===(w.page===1?'rule':w.page===2?'distance':'none')).at(-1);
 return `<section class="price-turn">${t}${last?`<aside class="price-feedback"><strong>Last check · ${Object.entries(last.raw).map(([k,v])=>`${esc(k)}: ${esc(v)}`).join(', ')}</strong><p>${esc(last.feedback)}</p></aside>`:''}${btn('data-price-help','Show me how')}${w.help.includes(`page-${w.page}`)?`<aside class="price-help"><h3>A worked example</h3><p>${esc(helpText(w))}</p>${hearButton(helpText(w),'Hear the example','en')}</aside>`:''}</section>`;}
export function priceRefusal(){return `<section class="price-page" data-price-root><h1 id="price-turn" tabindex="-1">The Courier’s Price</h1><p>This model could not be opened while keeping your notebook exportable. Your earlier work is unchanged.</p><div class="price-actions"><a href="#notes">Download your notes</a><a href="#desk">Return to the Desk</a></div></section>`;}
export function pricePage(state){const v=priceView(state),w=v.work;return `<div class="price-page" data-price-root lang="en"><header><a class="back" href="#desk">Back to the Keeper’s Desk</a><p class="price-kicker">A teaching bench · invented delivery prices</p><h1>The Courier’s Price</h1><p>Pip needs a price card for a delivery. Try a distance, name the rule, then work backwards from a total.</p></header>${v.status==='unavailable'?'<h2 id="price-turn" tabindex="-1">Your earlier price pages are kept safe</h2><p>This version cannot edit that saved format. Other places are open.</p><a href="#notes">Open Grown-up notes</a>':`<div class="price-cards" role="group" aria-label="Price cards">${v.cards.map(c=>c.unreadable?`<p>Earlier ${esc(c.title)} work is retained; this card cannot be edited here.</p>`:btn(`data-price-start="${esc(c.id)}" aria-pressed="${state.slopeBench?.currentId===c.id&&!!w}"`,c.title)).join('')}</div>${w?`<nav class="price-pages" aria-label="Lesson pages">${pricePages.map((s,n)=>btn(`data-price-page="${n}" aria-current="${w.page===n?'step':'false'}"`,`${n+1}. ${s}`,w.page===n)).join('')}</nav>${source(w.source)}<div class="price-layout">${turn(w)}${w.page!==3?`<aside class="price-reference">${graph(w.source,w.x)}${table(w.source,w.x)}</aside>`:''}</div><nav class="price-actions" aria-label="Previous and next page">${w.page>0?btn(`data-price-page="${w.page-1}"`,'Previous page'):''}${w.page<3?btn(`data-price-page="${w.page+1}"`,'Next page',true):''}</nav>`:'<h2 id="price-turn" tabindex="-1">Choose a price card to begin</h2><p>Use any amount of help. The same card will be waiting when you return.</p>'}`}<p id="price-status" role="status" aria-live="polite" tabindex="-1"></p><footer><a class="secondary" href="#post">Visit the Post Office</a><a class="secondary" href="#desk">Return to the Desk</a></footer></div>`;}
export function priceNotes(state){if(!Object.hasOwn(state,'slopeBench'))return '';const v=priceView(state);return `<details class="panel"><summary>The Courier’s Price · supported model practice</summary><p>Shown price cards, pictures and tables support every response. Checks do not establish independent recall, equation fluency or course completion. Typed explanations are human-read and ungraded. Each check keeps the help shown before it; first/latest kept pages retain their own sources and drafts.</p>${v.status==='unavailable'?'<p>Earlier format retained unchanged.</p>':Object.entries(state.slopeBench.cases).map(([key,w])=>`<h3>${esc(validPriceTitle(w,key))}</h3>${v.cards.some(c=>c.id===key&&!c.unreadable)?`<p>${w.checks?.length||0} recent checks. Latest kept page: ${w.kept?'yes':'not yet'}.</p>`:'<p>Earlier card retained unchanged.</p>'}`).join('')}<details><summary>Saved sources, checks, help and kept versions</summary><pre>${esc(JSON.stringify(state.slopeBench,null,2))}</pre></details></details>`;}
const validPriceTitle=(w,key)=>typeof w?.source?.title==='string'?w.source.title:key;
export function bindPrice(state,{save,render,focus,canExport,explorerId,isActive}){const root=document.querySelector('[data-price-root]');if(!root)return;const owner=explorerId?.(),route=location.hash,o={canExport};const live=el=>root.isConnected&&el.isConnected&&root.contains(el)&&location.hash===route&&(!isActive||isActive())&&explorerId?.()===owner;const say=(t,takeFocus=true)=>{const el=document.querySelector('#price-status');if(el){el.textContent=t;if(takeFocus)el.focus();}};const fail=()=>say('This change could not be kept safely. Earlier work is unchanged; download your notes and keep exploring.');const redraw=(message='',target='#price-turn')=>{stopSpeech();save();render();if(message){const el=document.querySelector('#price-status');if(el)el.textContent=message;}focus?.(target);};const clicks=(sel,fn)=>root.querySelectorAll(sel).forEach(b=>b.addEventListener('click',()=>{if(live(b))fn(b);}));
 clicks('[data-price-start]',b=>startPrice(state,b.dataset.priceStart,o)?redraw():fail());
 clicks('[data-price-page]',b=>setPricePage(state,Number(b.dataset.pricePage),o)?redraw():fail());
 clicks('[data-price-delta]',b=>{const w=priceView(state).work,n=w.x+Number(b.dataset.priceDelta);if(n<0||n>6)return say('This model covers 0–6 kilometers.',false);if(!setPriceX(state,n,o))return fail();redraw(`${n} kilometers: ${equation(w.source,n)}`,`[data-price-delta="${b.dataset.priceDelta}"]`);});
 const distance=root.querySelector('[data-price-x]');
 distance?.addEventListener('input',()=>{if(!live(distance))return;const n=priceInteger(distance.value);if(n===null||n>6)return;if(!setPriceX(state,n,o))return fail();save();const template=document.createElement('template');template.innerHTML=pricePage(state);for(const selector of ['.price-reference .price-graph','.price-reference .price-table','.price-batches','#price-x-state']){const old=root.querySelector(selector),next=template.content.querySelector(selector);if(old&&next)old.replaceWith(next);}say(`${n} kilometers: ${equation(priceView(state).work.source,n)}`,false);});
 distance?.addEventListener('change',()=>{if(!live(distance))return;const n=priceInteger(distance.value);if(n===null||n>6)say('Choose a whole distance from 0 to 6 kilometers.',false);});
 distance?.addEventListener('keydown',e=>{if(e.key==='Enter')e.preventDefault();});
 root.querySelectorAll('[data-price-field]').forEach(el=>el.addEventListener('input',()=>{if(!live(el))return;if(!setPriceField(state,el.dataset.priceField,el.value,o))return fail();save();}));
 clicks('[data-price-help]',()=>showPriceHelp(state,o)?redraw('Worked example opened.','#price-status'):fail());
 clicks('[data-price-check]',b=>{const r=checkPrice(state,b.dataset.priceCheck,o);if(!r)return fail();if(!r.recorded)return say(r.feedback);redraw(r.feedback,'#price-status');});
 clicks('[data-price-keep]',()=>keepPrice(state,o)?redraw('Page kept. You can change it and keep a later version.','#price-status'):fail());
}
